package bons.furious.patch.mcreator_pv_c49;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * mcreator_shared_default_player_variables (since 1.0.49): which mod and which PlayerVariables class each carrier mixin
 * serves. Generated by tools/mixedproof/McreatorPvC49Census.py --write from the build census; keep the carriers and
 * this table equal (the census writes both).
 */
public final class PvTargets {
    /** One carrier: its mixin class, the mod id that ships its targets and the PlayerVariables class (internal name). */
    public record Target(String mixin, String modId, String pv) {}

    static final String PKG = "bons.furious.mixin.mcreator_pv_c49.";
    public static final Map<String, Target> BY_MIXIN = new LinkedHashMap<>();

    static {
        // BEGIN TARGETS (generated)
        add("AnotherflashlightmodportPvCarrier", "anotherflashlightmodport", "net/mcreator/anotherflashlightmodport/network/AnotherflashlightmodportModVariables$PlayerVariables");
        add("BenssharksPvCarrier", "benssharks", "net/mcreator/sharks/network/BenssharksModVariables$PlayerVariables");
        add("BloblingsPvCarrier", "bloblings", "net/mcreator/bloblings/network/BloblingsModVariables$PlayerVariables");
        add("BloblingsGenesisPvCarrier", "bloblings_genesis", "net/mcreator/bloblingsgenesis/network/BloblingsGenesisModVariables$PlayerVariables");
        add("BornInChaosV1PvCarrier", "born_in_chaos_v1", "net/mcreator/borninchaosv/network/BornInChaosV1ModVariables$PlayerVariables");
        add("CallOfYucutanPvCarrier", "call_of_yucutan", "net/mcreator/callofyucutan/network/CallOfYucutanModVariables$PlayerVariables");
        add("CosmosPvCarrier", "cosmos", "net/lointain/cosmos/network/CosmosModVariables$PlayerVariables");
        add("GoblinsTyrannyPvCarrier", "goblins_tyranny", "goblinstyranny/network/GoblinsTyrannyModVariables$PlayerVariables");
        add("LuminousBeastsPvCarrier", "luminous_beasts", "net/mcreator/luminousbeasts/network/LuminousBeastsModVariables$PlayerVariables");
        add("ParticlepresetsPvCarrier", "particlepresets", "net/particleeffects/network/ParticlepresetsModVariables$PlayerVariables");
        add("RealmrpgQuestsPvCarrier", "realmrpg_quests", "net/mcreator/realmrpgquests/network/RealmrpgQuestsModVariables$PlayerVariables");
        // END TARGETS
    }

    private PvTargets() {
    }

    private static void add(String mixin, String modId, String pv) {
        BY_MIXIN.put(PKG + mixin, new Target(PKG + mixin, modId, pv));
    }
}
